import sys
import heapq

def find(parent, x):
    if parent[x] != x:
        parent[x] = find(parent, parent[x])
    return parent[x]

def union(parent, rank, x, y):
    rootX = find(parent, x)
    rootY = find(parent, y)
    if rootX != rootY:
        if rank[rootX] > rank[rootY]:
            parent[rootY] = rootX
        elif rank[rootX] < rank[rootY]:
            parent[rootX] = rootY
        else:
            parent[rootY] = rootX
            rank[rootX] += 1

def kruskal(n, edges):
    parent = list(range(n + 1))
    rank = [0] * (n + 1)
    mst_edges = []
    total_cost = 0
    for cost, u, v in edges:
        if find(parent, u) != find(parent, v):
            union(parent, rank, u, v)
            mst_edges.append((u, v, cost))
            total_cost += cost
    return mst_edges

def process(n, m, edges):
    edges.sort()
    mst_edges = kruskal(n, edges)
    mst_set = set((min(u, v), max(u, v)) for u, v, _ in mst_edges)
    result = [-1] * m
    edge_map = {}
    for i, (u, v, cost) in enumerate(edges):
        edge_map[(min(u, v), max(u, v))] = i
    for u, v, cost in edges:
        if (u, v) not in mst_set:
            original_cost = cost
            for w in range(original_cost + 1, 10**9 + 1):
                temp_edges = [(cost if (u, v) != (min(a, b), max(a, b)) else w, a, b) for a, b, cost in edges]
                new_mst_edges = kruskal(n, temp_edges)
                new_mst_set = set((min(u, v), max(u, v))for u, v, _ in new_mst_edges)
                if (u, v) in new_mst_set:
                    result[edge_map[(u, v)]] = w
                    break
    return result

def main():
    import sys
    input = sys.stdin.read().split()
    index = 0
    n = int(input[index])
